<template>
  <main class="home" v-loading="loading">
    <header class="hero"><div class="hero-copy"><p class="eyebrow">CAMPUS MOBILITY / 校园出行</p><h1>{{ greeting }}，{{ user.nickName || user.name }}。</h1><p>{{ isAdmin ? '车辆、订单和校园出行情况，都在这里。' : '今天也从容出发，下一站就在校园里。' }}</p><div class="hero-actions"><el-button type="primary" @click="go(isAdmin ? '/campus-reports/overview' : '/campus-ride/available')">{{ isAdmin ? '查看运营报表' : '寻找可借车辆' }}</el-button><el-button plain @click="go(isAdmin ? '/bikeStation/manage' : '/bikeStation/browse')">查看校园站点</el-button></div></div><div class="hero-route" aria-hidden="true"><i></i><b></b><span>01 / 02</span></div></header>
    <section class="overview"><div class="section-title"><div><p class="eyebrow dark">TODAY AT A GLANCE</p><h2>{{ isAdmin ? '运营概览' : '你的出行概览' }}</h2></div><el-button text icon="Refresh" :loading="loading" @click="load">刷新</el-button></div>
      <div v-if="isAdmin" class="metrics"><article><span>车辆总数</span><strong>{{ value(report?.vehicles?.total) }}</strong><small>当前车辆快照</small></article><article><span>空闲车辆</span><strong>{{ value(report?.vehicles?.idle) }}</strong><small>按车辆状态统计</small></article><article><span>完成订单</span><strong>{{ value(report?.orders?.completed) }}</strong><small>累计已完成租借</small></article><article><span>累计实收</span><strong>{{ money(report?.bills?.cashReceived) }}</strong><small>根据支付记录汇总</small></article></div>
      <div v-else class="metrics"><article><span>可借车辆</span><strong>{{ value(available) }}</strong><small>启用站点可用车辆</small></article><article><span>开放站点</span><strong>{{ value(stations) }}</strong><small>可查看与归还</small></article><article><span>当前订单</span><strong class="status-text">{{ currentOrder === undefined ? '—' : currentOrder ? (currentOrder.status === 'exception' ? '异常' : '进行中') : '暂无' }}</strong><small>{{ currentOrder ? currentOrder.vehicleNo : '借车后在此查看' }}</small></article><article><span>待缴账单</span><strong>{{ value(unpaid) }}</strong><small>请结清后再借车</small></article></div>
    </section>
    <section class="quick"><div class="section-title"><div><p class="eyebrow dark">QUICK ACCESS</p><h2>常用功能</h2></div></div><div class="quick-grid"><button v-for="item in shortcuts" :key="item.path" class="quick-card" type="button" @click="go(item.path)"><span class="quick-icon">{{ item.icon }}</span><span><strong>{{ item.title }}</strong><small>{{ item.note }}</small></span><b>↗</b></button></div></section>
  </main>
</template>
<script setup name="Index">
import useUserStore from '@/store/modules/user'
import { listAvailableVehicles } from '@/api/campus/vehicle'
import { browseStations } from '@/api/bike/station'
import { getMyRentals } from '@/api/campus/rental'
import { listMyBills } from '@/api/campus/bill'
import { getCampusReport } from '@/api/campus/report'
const user=useUserStore(),router=useRouter(),loading=ref(false),report=ref(null),available=ref(null),stations=ref(null),unpaid=ref(null),currentOrder=ref(undefined)
const isAdmin=computed(()=>user.roles.includes('admin'))
const greeting=computed(()=>{const h=new Date().getHours();return h<11?'早上好':h<18?'下午好':'晚上好'})
const value=v=>v==null?'—':v
const money=v=>v==null?'—':'¥'+Number(v).toFixed(2)
const shortcuts=computed(()=>isAdmin.value?[{icon:'车',title:'车辆管理',note:'维护车辆与状态',path:'/vehicle-admin/vehicle'},{icon:'站',title:'站点管理',note:'查看站点与车辆分布',path:'/bikeStation/manage'},{icon:'单',title:'租借订单',note:'查询和处理订单',path:'/campusRental/admin'},{icon:'图',title:'运营报表',note:'查看业务数据',path:'/campus-reports/overview'}]:[{icon:'骑',title:'可借车辆',note:'找到一辆空闲车',path:'/campus-ride/available'},{icon:'站',title:'校园站点',note:'查看开放站点',path:'/bikeStation/browse'},{icon:'单',title:'我的租借',note:'查看订单和还车',path:'/campusRental/mine'},{icon:'费',title:'我的账单',note:'查看与结清费用',path:'/my-expenses/bills'}])
function go(path){router.push(path)}
async function load(){loading.value=true;try{if(isAdmin.value){const r=await getCampusReport();report.value=r.data}else{const results=await Promise.allSettled([listAvailableVehicles({pageNum:1,pageSize:1}),browseStations({pageNum:1,pageSize:1}),getMyRentals({pageNum:1,pageSize:1}),listMyBills({pageNum:1,pageSize:1,status:'unpaid'})]);available.value=results[0].status==='fulfilled'?results[0].value.total:null;stations.value=results[1].status==='fulfilled'?results[1].value.total:null;currentOrder.value=results[2].status==='fulfilled'?(results[2].value.rows.find(x=>['ongoing','exception'].includes(x.status))||null):undefined;unpaid.value=results[3].status==='fulfilled'?results[3].value.total:null}}finally{loading.value=false}}
load()
</script>
<style scoped>
.home{min-height:calc(100vh - 84px);padding:24px;background:#f2f7f4;color:#193d38}.hero{position:relative;display:flex;min-height:230px;overflow:hidden;padding:34px 38px;border-radius:12px;background:#123f3b;color:#f1faf2}.hero-copy{position:relative;z-index:1}.eyebrow{margin:0;color:#86ddbb;font-size:10px;font-weight:700;letter-spacing:.18em}.hero h1{margin:14px 0 10px;font-size:29px;line-height:1.35}.hero p:not(.eyebrow){color:#b7d7c8;font-size:13px}.hero-actions{display:flex;gap:10px;margin-top:22px}.hero-actions :deep(.el-button){margin:0}.hero-route{position:absolute;right:7%;top:-90px;width:360px;height:360px;border:1px solid #397468;border-radius:50%}.hero-route i,.hero-route b{position:absolute;inset:35px;border:1px solid #397468;border-radius:50%}.hero-route b{inset:75px}.hero-route span{position:absolute;left:42%;top:49%;font-size:10px;letter-spacing:.14em;color:#85c9ac}.overview,.quick{margin-top:22px}.section-title{display:flex;justify-content:space-between;align-items:end;margin-bottom:14px}.dark{color:#318d77}.section-title h2{margin:7px 0 0;font-size:19px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.metrics article,.quick-card{min-width:0;background:#fff;border:1px solid #dfebe3;border-radius:9px}.metrics article{padding:21px}.metrics span,.metrics small{display:block;color:#789187;font-size:12px}.metrics strong{display:block;margin:14px 0 9px;font-size:27px;color:#173f37}.metrics strong.status-text{font-size:22px}.quick-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.quick-card{display:flex;align-items:center;gap:13px;padding:18px;text-align:left;color:#173f37;cursor:pointer;transition:border-color .18s,transform .18s}.quick-card:hover{border-color:#92cdb1;transform:translateY(-2px)}.quick-icon{display:grid;place-items:center;flex:none;width:42px;height:42px;border-radius:10px;background:#e8f5ec;color:#25836d;font-size:16px}.quick-card strong,.quick-card small{display:block}.quick-card strong{font-size:14px}.quick-card small{margin-top:6px;color:#849b91;font-size:12px}.quick-card b{margin-left:auto;color:#8bb3a1;font-size:15px}@media(max-width:1000px){.metrics,.quick-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.home{padding:12px}.hero{padding:26px;min-height:210px}.hero h1{font-size:23px}.hero-route{opacity:.3;right:-180px}.metrics,.quick-grid{gap:8px}.metrics article{padding:15px}.quick-card{padding:13px}.quick-icon{width:34px;height:34px}}@media(prefers-reduced-motion:reduce){.quick-card{transition:none}.quick-card:hover{transform:none}}
.hero-actions :deep(.el-button--primary){--el-button-bg-color:#238b70;--el-button-border-color:#238b70;--el-button-hover-bg-color:#2ca082;--el-button-hover-border-color:#2ca082}
</style>
